"""The World Today - one front-page image summing up 18 November 2026.

Writes the pre-rendered 1024x1024 newspaper front page to /output/entry.png
(or $MAKEFUN_OUTPUT_DIR/entry.png).

Stdlib only: the image bytes travel as base64 in this file, so the program
runs in a bare python:3.13-slim container with no Pillow and no fonts. No
network, no clock, no randomness: every run writes identical bytes.
The embedded image's SHA256 is
b445c6614d3ea2320b8710c63e458263f8201b0a910337758cf1e8171f1c5edd.

Run:  python3 main.py
"""

import base64
import os
from pathlib import Path

# The verified front-page PNG (1024x1024, 107793 bytes).
IMAGE_B64 = ""


def main():
    out_dir = Path(os.environ.get("MAKEFUN_OUTPUT_DIR", "/output"))
    out_dir.mkdir(parents=True, exist_ok=True)
    out = out_dir / "entry.png"
    out.write_bytes(base64.b64decode(IMAGE_B64))
    print("wrote", out, (1024, 1024))


if __name__ == "__main__":
    main()
